function getSiblings(q){
  const b=q.n.replace(/[a-g]$/,'');
  return QS.filter(s=>s.y===q.y&&s.d===q.d&&s.n.replace(/[a-g]$/,'')==b&&s.sub!=='')
           .sort((a,x)=>a.sub<x.sub?-1:1);
}
function countQs(t,l){return QS.filter(q=>q.t===t&&q.l===l&&q.d!=='C').length;}

function initHome(){
  document.getElementById('topicGrid').innerHTML=TOPICS.map(t=>`
    <div class="topic-card${QS.filter(q=>q.t===t.id&&q.d!=='C').length===0?' dim':''}" id="tc-${t.id}"
         onclick="selectTopic('${t.id}')" style="--tc:${t.color};--tc-rgb:${t.rgb}">
      <span class="topic-icon">${t.icon}</span><div class="topic-name">${t.label}</div>
      <div class="topic-count">${QS.filter(q=>q.t===t.id&&q.d!=='C').length} uppgifter</div>
      <div class="topic-check">✓</div></div>`).join('');
  renderLevels();
  document.getElementById('cGrid').innerHTML=C_YEARS.map(y=>{
    const n=C_EXAMS[y].questions.length;
    return `<div class="c-card" id="cc-${y}" onclick="selectCYear('${y}')">
      <span class="c-icon">📝</span><div class="c-name">NP ${y}</div>
      <div class="c-count">Delprov C · ${n} delfrågor</div>
      <div class="c-check">✓</div></div>`;
  }).join('');
}
