function initExtraGrid(){
  const grid = document.getElementById('extraGrid');
  if(EXTRA_TASKS.length === 0) return; // keep placeholder
  grid.innerHTML = EXTRA_TASKS.filter(t=>t&&t.id).map(t => `
    <div class="extra-card" id="ec-${t.id}" onclick="selectExtra('${t.id}')">
      <img src="${t.img}" alt="${t.title}" onerror="this.style.display='none'">
      <div class="e-title">${t.title}</div>
      <div class="e-sub">${t.sub}</div>
      <div class="e-check">✓</div>
    </div>`).join('');
}

function selectExtra(id){
  selExtra = id;
  selCYear = null; selTopic = null; selLevel = null;
  document.querySelectorAll('.extra-card').forEach(c=>c.classList.remove('sel'));
  document.querySelectorAll('.c-card,.topic-card,.level-card').forEach(c=>c.classList.remove('sel'));
  document.getElementById('ec-'+id)?.classList.add('sel');
  document.getElementById('startBtnExtra').disabled = false;
  document.getElementById('startBtnC').disabled = true;
  document.getElementById('startBtnAE').disabled = true;
}

function startPracticeExtra(){
  if(!selExtra) return;
  const task = EXTRA_TASKS.filter(t=>t&&t.id).find(t=>t.id===selExtra);
  if(!task) return;
  mode = 'extra';
  session = {correct:0, total:0}; chatHistory = [];
  
    document.getElementById('sesStats')?.style && (document.getElementById('sesStats').style.display='none');

  // Show in split layout with image on left, chat on right
  const pscreen = document.getElementById('screenPractice');
  pscreen.innerHTML = `
    <div class="split-layout" id="splitLayout">
      <div class="split-left" id="splitLeft">
        ${task.b64key && EXTRA_B64[task.b64key] ? `<div class="page-wrap"><img src="data:image/jpeg;base64,${EXTRA_B64[task.b64key]}" alt="${task.title}" style="width:100%;display:block"></div>` : task.img ? `<div class="page-wrap"><img src="${task.img}" alt="${task.title}" style="width:100%;display:block"></div>` : ''}
        <div id="extraTextPanel" class="page-wrap-text" style="background:#fff;padding:24px 28px;border-radius:14px;border:2px solid rgba(255,255,255,0.14);font-size:1rem;line-height:1.85;color:#111;white-space:pre-wrap;margin-top:${(task.b64key||task.img)?'8px':'0'}"></div>
      </div>
      <div class="split-right" id="splitRight">
        <div class="p-topbar">
          <div class="badges">
            <span class="badge" style="border-color:#7B68EE;color:#7B68EE">${task.title} · ${task.sub}</span>
          </div>
        </div>
        <div id="practiceArea">
          <div class="q-banner">
            <div class="q-banner-label">Extra uppgift</div>
            <div class="q-banner-main">${task.title}</div>
            <div class="q-banner-meta">${task.sub}</div>
          </div>
          <div class="ans-wrap">
            <textarea class="ans-input" id="ansInput" placeholder="Skriv ditt svar här…" rows="3"
              onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();checkAns();}"></textarea>
          </div>
          <div class="act-row">
            <button class="btn-check" id="btnCheck" onclick="checkAns()">Kontrollera svar</button>
            <button class="btn-sm" onclick="getHint()">💡 Ledtråd</button>
          </div>
          <div id="hintArea"></div>
          <div id="fbArea"></div>
        </div>
        <div class="chat-area" id="chatArea" style="display:none">
          <div class="chat-history" id="chatHistory"></div>
          <div class="chat-input-row">
            <input class="chat-input" id="chatInput" placeholder="Skriv en följdfråga…"
              onkeydown="if(event.key==='Enter')sendChat()">
            <button class="chat-send" id="chatSend" onclick="sendChat()">Skicka</button>
          </div>
        </div>
      </div>
    </div>`;

  // Set curQ context for sendChat
  curQ = {n: task.title, y: '', d: 'extra', extraId: task.id, img: null, img2: null, img3: null, b64: task.b64key ? EXTRA_B64[task.b64key] : null, text: task.text||'', ak: '', sub: '', sub_txt: ''};
  // Mark as worked on immediately when opened
  markTaskComplete(task.id);

  showScreen('Practice');
  // Set task text safely after DOM is ready
  const textPanel = document.getElementById('extraTextPanel');
  if(textPanel) textPanel.textContent = task.text || '';
  document.getElementById('ansInput')?.focus();
}

function showScreen(n){
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  document.getElementById('screen'+n).classList.add('active');
  document.getElementById('btnHome').classList.toggle('active',n==='Home');
  document.getElementById('btnHist').classList.toggle('active',n==='History');
  // Y7-knappen är inte en separat skärm — bara aktiv när goY7 sätter den
  const y7Btn=document.getElementById('btnY7');
  if(y7Btn) y7Btn.classList.remove('active');
}
function goHome(){
  // Restore screenPractice to original AE structure if it was replaced by C split-layout
  const ps=document.getElementById('screenPractice');
  if(document.getElementById('splitLayout')){
    ps.innerHTML=`
      <div class="practice">
        <div class="p-topbar"><div class="badges" id="badgeRow"></div><span class="q-counter" id="qCounter">#1</span></div>
        <div class="prog-track"><div class="prog-fill" id="progFill" style="width:0%"></div></div>
        <div id="practiceArea"></div>
        <div class="ses" id="sesStats" style="display:none">
          <div class="sec-label" style="margin-bottom:9px"><strong>Din session</strong></div>
          <div class="score-grid">
            <div class="score-card"><span class="score-num" id="sTotal" style="color:var(--accent)">0</span><div class="score-lbl">Uppgifter</div></div>
            <div class="score-card"><span class="score-num" id="sCorrect" style="color:var(--green)">0</span><div class="score-lbl">Rätt</div></div>
            <div class="score-card"><span class="score-num" id="sPct" style="color:var(--teal)">—</span><div class="score-lbl">Träffsäkerhet</div></div>
          </div>
        </div>
      </div>`;
  }
  loading=false;
  showScreen('Home');
  // Re-render extra grid to show completion badges
  initExtraGrid();
  initEEGrid();
  // Rensa Y7-val vid hemgång
  selY7Prov=null; selY7Topic=null;
  document.querySelectorAll('.y7-card').forEach(c=>c.classList.remove('sel'));
  const y7p=document.getElementById('startBtnY7Prov');if(y7p)y7p.disabled=true;
  const y7t=document.getElementById('startBtnY7Topic');if(y7t)y7t.disabled=true;
  updateCompletionMarkers();
}
function goHistory(){renderHistory();showScreen('History');}
function goY7(){
  // Säkerställ att vi är på hemskärmen (återställ practice-layout om den ändrats)
  const ps=document.getElementById('screenPractice');
  if(document.getElementById('splitLayout')){
    ps.innerHTML=`
      <div class="practice">
        <div class="p-topbar"><div class="badges" id="badgeRow"></div><span class="q-counter" id="qCounter">#1</span></div>
        <div class="prog-track"><div class="prog-fill" id="progFill" style="width:0%"></div></div>
        <div id="practiceArea"></div>
        <div class="ses" id="sesStats" style="display:none">
          <div class="sec-label" style="margin-bottom:9px"><strong>Din session</strong></div>
          <div class="score-grid">
            <div class="score-card"><span class="score-num" id="sTotal" style="color:var(--accent)">0</span><div class="score-lbl">Uppgifter</div></div>
            <div class="score-card"><span class="score-num" id="sCorrect" style="color:var(--green)">0</span><div class="score-lbl">Rätt</div></div>
            <div class="score-card"><span class="score-num" id="sPct" style="color:var(--teal)">—</span><div class="score-lbl">Träffsäkerhet</div></div>
          </div>
        </div>
      </div>`;
  }
  loading=false;
  showScreen('Home');
  // Markera Åk 7-knappen som aktiv (showScreen aktiverade btnHome)
  document.getElementById('btnHome').classList.remove('active');
  document.getElementById('btnY7').classList.add('active');
  // Scrolla till åk 7-sektionen
  setTimeout(()=>{
    const sec=document.querySelector('.y7-section');
    if(sec) sec.scrollIntoView({behavior:'smooth', block:'start'});
  }, 50);
}

/* ══ AE MODE ══════════════════════════════════════════════════════════════ */
function startPracticeAE(){
  mode='ae';session={correct:0,total:0};usedIds.clear();questionQueue=[];
  document.getElementById('sesStats').style.display='none';
  const tp=TOPICS.find(t=>t.id===selTopic),lv=LEVELS.find(l=>l.id===selLevel);
  document.getElementById('badgeRow').innerHTML=
    '<span class="badge acc">'+tp.label+'</span><span class="badge lv-'+selLevel+'">'+lv.name+'</span>';
  showScreen('Practice');loadQ();
}
function pickFresh(){
  let pool=QS.filter(q=>q.t===selTopic&&q.l===selLevel&&q.d!=='C'&&!usedIds.has(q.id));
  if(!pool.length){usedIds.clear();if(curQ)usedIds.add(curQ.id);
    pool=QS.filter(q=>q.t===selTopic&&q.l===selLevel&&q.d!=='C'&&!usedIds.has(q.id));}
  return pool.length?pool[Math.floor(Math.random()*pool.length)]:null;
}

/* ══ C MODE ═══════════════════════════════════════════════════════════════ */
function startPracticeC(){
  mode='c';session={correct:0,total:0};usedIds.clear();chatHistory=[];
  document.getElementById('sesStats').style.display='none';
  questionQueue=[...C_EXAMS[selCYear].questions]
    .sort((a,b)=>a.ni!==b.ni?a.ni-b.ni:a.sub<b.sub?-1:1);
  document.getElementById('badgeRow').innerHTML=
    '<span class="badge" style="border-color:#C8A200;color:#C8A200">Delprov C · NP '+selCYear+'</span>';
  showScreen('Practice');
  renderCLayout();
}

function renderCLayout(){
  // Replace the practice div with split layout
  const pscreen=document.getElementById('screenPractice');
  pscreen.innerHTML=`
    <div class="split-layout" id="splitLayout">
      <div class="split-left" id="splitLeft"></div>
      <div class="split-right" id="splitRight">
        <div class="p-topbar">
          <div class="badges" id="badgeRow2"></div>
          <span class="q-counter" id="qCounter">#1</span>
        </div>
        <div class="prog-track"><div class="prog-fill" id="progFill" style="width:0%"></div></div>
        <div id="practiceArea"></div>
        <div class="ses" id="sesStats" style="display:none">
          <div class="sec-label" style="margin-bottom:9px"><strong>Din session</strong></div>
          <div class="score-grid">
            <div class="score-card"><span class="score-num" id="sTotal" style="color:var(--accent)">0</span><div class="score-lbl">Uppgifter</div></div>
            <div class="score-card"><span class="score-num" id="sCorrect" style="color:var(--green)">0</span><div class="score-lbl">Rätt</div></div>
            <div class="score-card"><span class="score-num" id="sPct" style="color:var(--teal)">—</span><div class="score-lbl">Träffsäkerhet</div></div>
          </div>
        </div>
      </div>
    </div>`;
  
  // Re-inject nav badges into new badgeRow2
  document.getElementById('badgeRow2').innerHTML=
    '<span class="badge" style="border-color:#C8A200;color:#C8A200">Delprov C · NP '+selCYear+'</span>';

  // Show all pages on the left
  const left=document.getElementById('splitLeft');
  const exam=C_EXAMS[selCYear];
  left.innerHTML=exam.pages.map(p=>
    `<div class="page-wrap"><img src="data:image/jpeg;base64,${p.img}" alt="Provsida" loading="lazy"></div>`
  ).join('');

  loadQ();
}

/* ══ LOAD QUESTION ════════════════════════════════════════════════════════ */
function loadQ(){
  loading=false;chatHistory=[];
  let q;
  if(questionQueue.length>0){
    q=questionQueue.shift();
  } else if(mode==='ae'){
    q=pickFresh();
    if(!q){showDone('Inga fler uppgifter – bra jobbat!');return;}
    const sibs=getSiblings(q);
    if(sibs.length>0){q=sibs[0];questionQueue=[...sibs.slice(1)];}
  } else {
    showDone('Klart! Du har besvarat alla delfrågor i Delprov C '+selCYear+'.');
    return;
  }
  usedIds.add(q.id);curQ=q;session.total++;
  document.getElementById('qCounter').textContent='#'+session.total;
  updateProg();renderQ(q);
}

function renderQ(q){
  const area=document.getElementById('practiceArea');
  const base=q.n.replace(/[a-g]$/,'');
  let hint='';
  if(questionQueue.length>0){
    if(mode==='c') hint=' · '+questionQueue.length+' frågor kvar';
    else{const c=questionQueue.filter(s=>s.n.replace(/[a-g]$/,'')==base).map(s=>base+s.sub);if(c.length)hint=' · fortsätter med '+c.join(', ');}
  }
  let instrMain='',instrSub='';
  if(q.sub){
    instrMain='Svara på uppgift <strong>'+q.n+'</strong>&nbsp;(delfråga&nbsp;'+q.sub+')';
    if(q.sub_txt&&q.sub_txt.trim())instrSub='<div class="q-banner-sub">'+esc(q.sub_txt)+'</div>';
  } else instrMain='Svara på uppgift <strong>'+q.n+'</strong>';

  const banner='<div class="q-banner"><div class="q-banner-label">Din uppgift</div>'
    +'<div class="q-banner-main">'+instrMain+'</div>'+instrSub
    +'<div class="q-banner-meta">NP '+q.y+' · Delprov '+q.d+(q.pts?' · '+q.pts:'')+hint+'</div></div>';

  // In AE mode: show page images above answer
  let pageHtml='';
  if(mode==='ae'){
    const imgs=[q.img,q.img2,q.img3].filter(Boolean);
    for(const f of imgs)
      pageHtml+=`<div class="page-wrap"><img src="images/${f}" alt="Provsida" loading="lazy"></div>`;
    if(!pageHtml)pageHtml='<div class="page-wrap-text">'+esc(q.main)+'</div>';
  }

  area.innerHTML=banner+pageHtml
    +'<div class="ans-wrap"><textarea class="ans-input" id="ansInput" placeholder="Ditt svar på uppgift '+q.n+'…" rows="2"'
    +' onkeydown="if(event.key===\'Enter\'&&!event.shiftKey){event.preventDefault();checkAns();}"></textarea></div>'
    +'<div class="act-row"><button class="btn-check" id="btnCheck" onclick="checkAns()">Kontrollera svar</button>'
    +'<button class="btn-sm" onclick="getHint()">💡 Ledtråd</button>'
    +(mode==='ae'?'<button class="btn-sm" onclick="skipQ()">Hoppa över</button>':'')
    +'</div><div id="hintArea"></div><div id="fbArea"></div>'
    // Follow-up chat (always visible after feedback is shown - rendered dynamically)
    +'<div class="chat-area" id="chatArea" style="display:none">'
    +'<div class="chat-history" id="chatHistory"></div>'
    +'<div class="chat-input-row">'
    +'<input class="chat-input" id="chatInput" placeholder="Ställ en följdfråga…"'
    +' onkeydown="if(event.key===\'Enter\')sendChat()">'
    +'<button class="chat-send" id="chatSend" onclick="sendChat()">Skicka</button>'
    +'</div></div>';

  document.getElementById('ansInput')?.focus();
}

function skipQ(){
  if(curQ&&curQ.sub){const b=curQ.n.replace(/[a-g]$/,'');questionQueue=questionQueue.filter(s=>s.n.replace(/[a-g]$/,'')!==b);}
  loadQ();
}

/* ══ CHECK ANSWER ═════════════════════════════════════════════════════════ */
async function checkAns(){
  const inp=document.getElementById('ansInput');
  const ans=(inp?.value||'').trim();
  if(!ans||loading)return;
  loading=true;
  const btn=document.getElementById('btnCheck');
  if(btn){btn.disabled=true;btn.innerHTML='<span class="spinner"></span> Bedömer…';}

  const sys = 'Du är en matematiklärare som bedömer elevens svar. '
    + 'REGEL 1: Svara med EXAKT ett JSON-objekt. Ingenting annat. '
    + 'REGEL 2: Fråga ALDRIG efter mer information. '
    + 'REGEL 3: Acceptera alla matematiskt ekvivalenta uttryck. Om elevens uttryck ger rätt numeriskt värde, sätt correct:true. '
    + 'REGEL 4: Om eleven skriver ett korrekt uttryck men inte ett färdigt tal, sätt correct:true men nämn i shortFeedback att det är bra att också ange det slutgiltiga numeriska svaret. '
    + 'REGEL 5: ALDRIG ändra bedömning inom samma svar. '
    + 'REGEL 6: shortFeedback 1-2 meningar, ingen markdown. '
    + 'FORMAT: {"correct":true,"shortFeedback":"..."} eller {"correct":false,"shortFeedback":"..."}';
  const subInfo=curQ.sub?'\n\nDelfråga '+curQ.sub+(curQ.sub_txt?' ('+curQ.sub_txt+')':'')+'.\n':'\n\nUppgift '+curQ.n+'.\n';
  const akInfo=curQ.ak?'\n\nBedömningsanvisning:\n'+curQ.ak+'\n\nVIKTIGT: Basera bedömningen ENBART på bedömningsanvisningen.':'';

  try{
    const imgFiles=mode==='c'
      ? C_EXAMS[selCYear].pages.map(p=>({type:'b64',data:p.img}))
      : (mode==='extra'||mode==='ee')
        ? (curQ.b64 ? [{type:'b64',data:curQ.b64}] : [])
        : mode==='y7'
          ? (curQ.svg && Y7_FIG_B64[curQ.svg] ? [{type:'b64',data:Y7_FIG_B64[curQ.svg]}] : [])
          : [curQ.img,curQ.img2,curQ.img3].filter(Boolean).map(f=>({type:'file',data:f}));

    let pageCtxText;
    if(mode==='y7'){
      const hasFig = curQ.svg && Y7_FIG_B64[curQ.svg];
      pageCtxText = 'ÅK 7 UPPGIFT '+curQ.n+' (Nivå '+curQ.level+'):\n'+curQ.q
        + (hasFig ? '\n\n(Figuren från provet är bifogad som bild — använd den för att läsa exakta vinklar, mått och sträckmarkeringar.)' : '')
        + (curQ.facit?'\n\nFACIT (lärarens förslag): '+curQ.facit:'')
        + (curQ.lös?'\n\nFULLSTÄNDIG LÖSNING (lärarens förslag): '+curQ.lös:'')
        + '\n\nVIKTIGT: Bedöm elevens svar mot facit. Om bild finns, lita på det du ser i bilden — den är auktoritativ för geometriska detaljer. Acceptera matematiskt ekvivalenta svar (t.ex. 7,5 = 7.5 = 15/2). För algebrasvar: acceptera olika ordningar. För enheter: om facit har enhet (kr, cm, °) och eleven gett rätt tal utan enhet, sätt correct:true men nämn enheten i feedback. Om eleven har räknat rätt utifrån en rimlig tolkning av figuren — även om svaret skiljer sig från facit — sätt correct:true.';
    } else {
      pageCtxText = (mode==='extra'||mode==='ee')&&curQ.text
        ? 'UPPGIFT (hela texten):\n'+curQ.text
        : 'Provsida NP '+curQ.y+' Delprov '+curQ.d+'.';
    }
    const fullText = pageCtxText+subInfo+akInfo
      +'\n\nELEVENS SVAR: '+ans
      +'\n\nBedöm svaret ovan. Fråga INTE efter mer information. Svara DIREKT med JSON:'
      +'\n{"correct":true,"shortFeedback":"feedback"} eller {"correct":false,"shortFeedback":"feedback"}';

    let messages;
    if(imgFiles.length>0){
      const content=[];
      for(const img of imgFiles){
        const b64=img.type==='b64'?img.data:await fetchB64('images/'+img.data);
        content.push({type:'image',source:{type:'base64',media_type:'image/jpeg',data:b64}});
      }
      content.push({type:'text',text:fullText});
      messages=[{role:'user',content:content}];
    } else {
      // Text-only: send as plain string (simpler, more reliable)
      messages=[{role:'user',content:fullText}];
    }
    const raw=await callClaude(messages,sys);
    const fb=parseJSON(raw);const ok=fb.correct===true;
    if(ok)session.correct++;

    // Store for follow-up context
    chatHistory=[{
      role:'assistant',
      content:'Jag bedömde uppgift '+curQ.n+'. '+fb.shortFeedback+' '+fb.explanation
    }];

    history.unshift({label:'Uppgift '+curQ.n+' — NP '+curQ.y+' Delprov '+curQ.d,
      topic:curQ.d==='C'?'Delprov C':(TOPICS.find(t=>t.id===curQ.t)||{}).label||curQ.t,
      level:curQ.l,answer:ans,correct:ok});
    inp.disabled=true;

    document.getElementById('fbArea').innerHTML=(function(){
      var nextFn = mode==='y7' ? 'loadY7Q()' : 'loadQ()';
      var nxt=(mode==='extra'||mode==='ee')?'':
        '<button class="fb-btn fb-btn-next" onclick="'+nextFn+'">Nästa uppgift →</button>';
      var chat='<button class="fb-btn" onclick="document.getElementById(\'chatArea\').style.display=\'block\';document.getElementById(\'chatInput\').focus()">Ställ en fråga</button>';
      var btns=ok
        ?'<div class="fb-actions">'+chat+nxt+'</div>'
        :'<div class="fb-actions">'
          +'<button class="fb-btn" onclick="showHint()">💡 Få ett tips</button>'
          +'<button class="fb-btn" onclick="tryAgain()">🔄 Försök igen</button>'
          +chat+nxt+'</div>';
      // Visa lösning för y7-uppgifter
      var solBox = '';
      if(mode==='y7' && curQ){
        solBox = '<div class="sol-box" style="margin-top:10px">'
          + '<div class="sol-lbl">Facit</div>'
          + '<div style="font-weight:600;margin-bottom:6px">'+esc(curQ.facit||'')+'</div>'
          + (curQ.lös?'<div class="sol-lbl" style="margin-top:8px">Lösning</div><div>'+esc(curQ.lös)+'</div>':'')
          + '</div>';
      }
      return '<div class="fb '+(ok?'ok':'bad')+'">'  
        +'<div class="fb-head"><span class="fb-icon">'+(ok?'✅':'❌')+'</span>'
        +'<span class="fb-title">'+(ok?'Rätt svar!':'Fel svar')+'</span></div>'
        +'<div class="fb-short">'+esc(fb.shortFeedback||'')+'</div>'
        +solBox
        +btns
        +'<div id="hintFromBtn" style="display:none"></div>'
        +'</div>';
    })();
    updateProg();if(session.total>=3)showSes();
  }catch(e){
    var retryFn = mode==='y7' ? 'loadY7Q()' : 'loadQ()';
    document.getElementById('fbArea').innerHTML='<div class="fb bad"><div class="fb-short">⚠️ '+esc(e.message)+'</div>'
      +'<button class="next-btn" onclick="'+retryFn+'">Försök igen</button></div>';
  }finally{loading=false;}
}

/* ══ FOLLOW-UP CHAT ═══════════════════════════════════════════════════════ */
async function sendChat(){
  const input=document.getElementById('chatInput');
  const msg=(input?.value||'').trim();
  if(!msg||loading)return;
  input.value='';
  loading=true;
  document.getElementById('chatSend').disabled=true;

  // Add user message to display
  chatHistory.push({role:'user',content:msg});
  renderChatHistory();

  const sys='Du är en hjälpsam matematiklärare. Svara på svenska, kort och pedagogiskt. Använd ALDRIG markdown-syntax som **, ##, *, -, eller liknande. Skriv ren text med vanliga tecken. Du har alltid tillgång till hela uppgiften.';

  try{
    // Build messages: context + full chat history
    const imgFiles=mode==='c'
      ? C_EXAMS[selCYear].pages.map(p=>({type:'b64',data:p.img}))
      : (mode==='extra'||mode==='ee')
        ? (curQ.b64 ? [{type:'b64',data:curQ.b64}] : [])
        : mode==='y7'
          ? (curQ.svg && Y7_FIG_B64[curQ.svg] ? [{type:'b64',data:Y7_FIG_B64[curQ.svg]}] : [])
          : [curQ.img,curQ.img2,curQ.img3].filter(Boolean).map(f=>({type:'file',data:f}));

    let contextContent=[];
    for(const img of imgFiles){
      const b64=img.type==='b64'?img.data:await fetchB64('images/'+img.data);
      contextContent.push({type:'image',source:{type:'base64',media_type:'image/jpeg',data:b64}});
    }
    let ctxForChat;
    if(mode==='y7'){
      ctxForChat = 'Åk 7 uppgift '+curQ.n+' (Nivå '+curQ.level+'):\n'+curQ.q
        +(curQ.facit?'\n\nFacit: '+curQ.facit:'')
        +(curQ.lös?'\n\nLösning: '+curQ.lös:'');
    } else {
      ctxForChat = mode==='extra' && curQ.text
        ? 'Uppgift (hela texten):\n'+curQ.text+(curQ.ak?'\nBedömningsanvisning:\n'+curQ.ak:'')
        : 'Provsida NP '+curQ.y+' Delprov '+curQ.d+'.'+(curQ.ak?'\nBedömningsanvisning:\n'+curQ.ak:'');
    }
    if(mode==='extra' && !curQ.b64) contextContent=[];
    contextContent.push({type:'text', text:ctxForChat});

    // Multi-turn messages - ensure all content is properly formatted
    const messages=[];
    messages.push({role:'user',content:contextContent});
    for(const m of chatHistory.slice(0,-1)){
      messages.push({role:m.role, content:[{type:'text',text:String(m.content)}]});
    }
    messages.push({role:'user',content:[{type:'text',text:msg}]});

    const reply=await callClaude(messages,sys);
    chatHistory.push({role:'assistant',content:reply});
    renderChatHistory();
  }catch(e){
    chatHistory.push({role:'assistant',content:'⚠️ '+e.message});
    renderChatHistory();
  }finally{loading=false;document.getElementById('chatSend').disabled=false;}
}

function renderChatHistory(){
  const el=document.getElementById('chatHistory');
  if(!el)return;
  el.innerHTML=chatHistory.filter(m=>m.role!=='assistant'||chatHistory.indexOf(m)>0).map(m=>
    `<div class="chat-msg ${m.role==='user'?'user':'ai'}">${esc(m.content)}</div>`
  ).join('');
  el.scrollTop=el.scrollHeight;
}

/* ══ HINT ═════════════════════════════════════════════════════════════════ */
function showHint(){
  getHint(); // reuse getHint which now handles both hintArea and hintFromBtn
}
function tryAgain(){
  // Re-enable the answer input and check button
  const inp=document.getElementById('ansInput');
  const btn=document.getElementById('btnCheck');
  if(inp){inp.disabled=false;inp.value='';inp.focus();}
  if(btn){btn.disabled=false;btn.innerHTML='Kontrollera svar';}
  document.getElementById('fbArea').innerHTML='';
  const _ca=document.getElementById('chatArea');if(_ca)_ca.style.display='none';
}

async function getHint(){
  if(loading)return;
  // Determine target element - hintArea for normal mode, hintFromBtn for feedback hints
  const ha=document.getElementById('hintArea')||document.getElementById('hintFromBtn');
  if(!ha)return;
  ha.style.display='block';
  // Y7-läge: använd inbyggd ledtråd om den finns
  if(mode==='y7' && curQ && curQ.ledtråd){
    ha.innerHTML='<div class="hint-box"><div class="hint-lbl">💡 Ledtråd</div>'+esc(curQ.ledtråd)+'</div>';
    return;
  }
  ha.innerHTML='<div class="hint-box"><div class="hint-lbl">💡 Ledtråd</div><div class="skel" style="height:13px;width:65%;margin-top:4px"></div></div>';
  loading=true;
  const sub=curQ.sub?' Delfråga '+curQ.sub+(curQ.sub_txt?': '+curQ.sub_txt:''):'';
  const extraCtx=mode==='extra'&&curQ.text?'\nUppgift: '+curQ.text:'';
  try{
    const imgFiles=mode==='c'
      ? C_EXAMS[selCYear].pages.map(p=>({type:'b64',data:p.img}))
      : mode==='extra'
        ? (curQ.b64?[{type:'b64',data:curQ.b64}]:[])
        : mode==='y7'
          ? (curQ.svg && Y7_FIG_B64[curQ.svg] ? [{type:'b64',data:Y7_FIG_B64[curQ.svg]}] : [])
          : [curQ.img,curQ.img2,curQ.img3].filter(Boolean).map(f=>({type:'file',data:f}));
    let messages;
    if(imgFiles.length>0){
      const content=[];
      for(const img of imgFiles){
        const b64=img.type==='b64'?img.data:await fetchB64('images/'+img.data);
        content.push({type:'image',source:{type:'base64',media_type:'image/jpeg',data:b64}});
      }
      content.push({type:'text',text:extraCtx+'\nGe en kort ledtråd (max 2 meningar) för uppgift '+curQ.n+sub+'. Avslöj INTE svaret.'});
      messages=[{role:'user',content}];
    } else {
      messages=[{role:'user',content:extraCtx+'\nGe en kort ledtråd (max 2 meningar) för uppgift '+curQ.n+sub+'. Avslöj INTE svaret.'}];
    }
    const h=await callClaude(messages,'Du är en hjälpsam matematiklärare. Svara på svenska, max 2 meningar. Skriv ren text utan markdown.');
    ha.innerHTML='<div class="hint-box"><div class="hint-lbl">💡 Ledtråd</div>'+esc(h)+'</div>';
  }catch(e){ha.innerHTML='';}finally{loading=false;}
}

/* ══ UTILS ════════════════════════════════════════════════════════════════ */
async function fetchB64(url){
  const r=await fetch(url);const b=await r.blob();
  return new Promise(res=>{const fr=new FileReader();fr.onload=()=>res(fr.result.split(',')[1]);fr.readAsDataURL(b);});
}
async function callClaude(messages,sys){
  const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},
    body:JSON.stringify({model:'claude-sonnet-4-5',max_tokens:800,system:sys,messages})});
  if(!r.ok){const e=await r.json().catch(()=>({}));throw new Error(e.error?.message||'API-fel '+r.status);}
  return(await r.json()).content?.[0]?.text||'';
}
function updateProg(){
  const p=session.total>0?Math.min((session.correct/session.total)*100,100):0;
  const pf=document.getElementById('progFill');
  if(pf) pf.style.width=p+'%';
  const ns=document.getElementById('navStat');
  if(session.total>0&&ns){ns.style.display='inline';ns.textContent=session.correct+'/'+session.total;}
}
function showSes(){
  const s=document.getElementById('sesStats');if(!s)return;
  s.style.display='block';
  const st=document.getElementById('sTotal');if(st)st.textContent=session.total;
  const sc=document.getElementById('sCorrect');if(sc)sc.textContent=session.correct;
  const sp=document.getElementById('sPct');if(sp)sp.textContent=Math.round((session.correct/session.total)*100)+'%';
}
function showDone(msg){
  const area=document.getElementById('practiceArea');
  if(area)area.innerHTML='<div class="fb ok" style="margin-top:0"><div class="fb-short">'+esc(msg)+'</div>'
    +'<button class="next-btn" onclick="goHome()">Välj nytt</button></div>';
}
function parseJSON(r){
  // Try direct parse first
  try{ return JSON.parse(r.replace(/```json|```/g,'').trim()); }catch(e){}
  // Try to extract JSON object from response
  const m = r.match(/\{[^{}]*"correct"[^{}]*\}/);
  if(m){ try{ return JSON.parse(m[0]); }catch(e){} }
  // Fallback: detect correct/incorrect from text
  const txt = r.toLowerCase();
  const correct = txt.includes('rätt') || txt.includes('korrekt') || txt.includes('"correct":true') || txt.includes('correct: true');
  return {correct: correct, shortFeedback: r.substring(0,200)};
}
function esc(s){return(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function renderHistory(){
  const list=document.getElementById('histList'),sub=document.getElementById('histSub'),hs=document.getElementById('histStats');
  sub.textContent='Dina senaste '+history.length+' uppgifter';
  if(!history.length){list.innerHTML='<div class="empty"><div class="e-icon">📚</div><div>Ingen historik än.</div></div>';hs.style.display='none';return;}
  const cor=history.filter(h=>h.correct).length;hs.style.display='block';
  document.getElementById('hTotal').textContent=history.length;
  document.getElementById('hCorrect').textContent=cor;
  document.getElementById('hPct').textContent=Math.round((cor/history.length)*100)+'%';
  list.innerHTML=history.map(h=>'<div class="hist-item"><div class="h-dot" style="background:'+(h.correct?'var(--green)':'var(--red)')+'"></div>'
    +'<div style="flex:1;overflow:hidden"><div class="h-q">'+esc(h.label)+'</div><div class="h-meta">'+esc(h.topic)+' · Nivå '+esc(h.level)+'</div></div>'
    +'<div class="h-result" style="color:'+(h.correct?'var(--green)':'var(--red)')+'">'+
    (h.correct?'✓':'✗')+'</div></div>').join('');
}


document.addEventListener('DOMContentLoaded', function(){
  initHome();
  initExtraGrid();
  initEEGrid();
  initY7();
  loadCompletedTasks();
});